package com.spai.portal.integration.controller;import java.util.*;import com.spai.portal.common.ApiResponse;import com.spai.portal.integration.domain.SyncJob;import com.spai.portal.integration.repository.SyncJobRepository;import com.spai.portal.integration.service.SyncService;import org.springframework.data.domain.Sort;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/admin/sync")@PreAuthorize("hasRole('ADMIN')")public class SyncController{private final SyncService service;private final SyncJobRepository jobs;public SyncController(SyncService service,SyncJobRepository jobs){this.service=service;this.jobs=jobs;}@PostMapping("/{source}/trigger")public ApiResponse<SyncJob>trigger(@PathVariable String source){return ApiResponse.ok(service.trigger(source));}@GetMapping public ApiResponse<List<SyncJob>>list(){return ApiResponse.ok(jobs.findAll(Sort.by(Sort.Direction.DESC,"startedAt")));}}
